style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://64.media.tumblr.com/7fbe1060e1a774823b21dd763ab46084/tumblr_pgbkgxbzAt1w0ynklo1_500.gif") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Optional: Make page elements semi-transparent */
    .container-main, .navbar, .content, .game-details-page, #header, footer {
        background-color: rgba(0, 0, 0, 0.6) !important;
        color: white !important;
    }

    /* Optional: Hide ads or empty white areas */
    .ad-container, .ads, .advertisement-section {
        display: none !important;
    }

    /* Optional: Smooth font rendering and dark text override */
    * {
        text-shadow: 1px 1px 2px black;
    }
}
